const seen = $getWorkflowStaticData('global');
const manual = $execution.mode === 'manual';
const calls = ($json.conversations || []).filter(c => c.status === 'done');
// First scheduled run: remember existing calls without processing them.
if (!manual && !seen.ids) { seen.ids = calls.map(c => c.conversation_id); return []; }
seen.ids = seen.ids || [];
// Manual test: the latest finished call. Scheduled: only calls not handled before.
const todo = manual ? calls.slice(0, 1) : calls.filter(c => !seen.ids.includes(c.conversation_id));
if (!manual) seen.ids = [...todo.map(c => c.conversation_id), ...seen.ids].slice(0, 500);
return todo.map(c => ({ json: { conversation_id: c.conversation_id } }));

const c = $json;
const transcript = (c.transcript || []).filter(t => t.message).map(t => (t.role === 'agent' ? 'Agent' : 'User') + ': ' + t.message).join('\n');
const collected = Object.fromEntries(Object.entries(c.analysis?.data_collection_results || {}).map(([k, v]) => [k, v.value]));
const start = c.metadata?.start_time_unix_secs;
return { json: {
  conversation_id: c.conversation_id,
  call_date: (start ? new Date(start * 1000) : new Date()).toISOString().slice(0, 10),
  transcript, collected_data: collected, summary: c.analysis?.transcript_summary || null,
} };

// Turn the sheet into rows, and pick the rows near the day the teacher named.
const values = $('Sheet: read rows').item.json.values || [];
const headers = (values[0] || []).map(v => String(v).trim());
const H = name => headers.indexOf(name);
const linkOf = cell => (String(cell || '').match(/https?:\/\/[^"\s)]+/) || [])[0] || null;
const rows = values.slice(1).map((v, k) => ({
  row_number: k + 2,
  day: String(v[H('Day')] ?? '').trim(),
  topic: String(v[H('Topic')] ?? '').trim(),
  group_a: v[H('Group A today')] ?? '', group_b: v[H('Group B today')] ?? '', group_c: v[H('Group C today')] ?? '',
  plan_cell: v[H('Plan')] ?? '', plan_url: linkOf(v[H('Plan')]),
  original_cell: v[H('Original plan')] ?? '', completed: v[H('Completed')] ?? '',
})).filter(r => r.day);
const said = String($('Prepare call').item.json.collected_data.day_number ?? '').replace(/[^0-9a-z]/gi, '');
const i = rows.findIndex(r => r.day === said);
const near = i < 0 ? rows.filter(r => !r.completed).slice(0, 6) : rows.slice(Math.max(0, i - 2), i + 3);
const tab = ($('Sheet: info').item.json.sheets.find(s => s.properties.title === 'Plan') || $('Sheet: info').item.json.sheets[0]).properties;
const folder = ($('Drive: find Updated plans').item.json.files || [])[0];
return { json: { headers, rows, plan_rows: near.map(({ row_number, plan_cell, original_cell, ...r }) => r),
  sheet_title: tab.title, sheet_gid: tab.sheetId, updated_folder_id: folder ? folder.id : null } };

const m = $('Match rows').item.json; const p = $json;
if (!p.row_number) return { json: { body: { valueInputOption: 'RAW', data: [] }, skipped: 'Could not find the day in the sheet' } };
const col = name => { const k = m.headers.findIndex(x => x.trim().toLowerCase() === name.toLowerCase()); return k < 0 ? null : String.fromCharCode(65 + k); };
const data = [];
const set = (name, v) => { const c = col(name); if (c && v != null && v !== '') data.push({ range: "'" + m.sheet_title + "'!" + c + p.row_number, values: [[v]] }); };
for (const [k, v] of Object.entries(p.feedback.sheet || {})) set(k, v);
const { sheet, ...stored } = p.feedback;
set('Feedback (JSON)', JSON.stringify(stored));
return { json: { body: { valueInputOption: 'RAW', data } } };

const c = $('Config').first().json, m = $('Match rows').item.json, p = $('Combine (ElevenLabs first)').item.json;
return { json: { teacher_email: c.teacher_email, sheet_id: c.teacher_sheet_id, sheet_url: 'https://docs.google.com/spreadsheets/d/' + c.teacher_sheet_id + '/edit',
  sheet_title: m.sheet_title, sheet_gid: m.sheet_gid, headers: m.headers, rows: m.rows, updated_folder_id: m.updated_folder_id,
  row_number: p.row_number, feedback: p.feedback, make_easier: p.make_easier } };

// AgenticOrg reply -> same 12 keys as the voice agent (empty object if it failed).
let o = $json.output;
if (typeof o === 'string') { try { o = JSON.parse(o.replace(/^[^{]*/, '').replace(/[^}]*$/, '')); } catch { o = null; } }
o = o && typeof o === 'object' ? o : {};
return { json: { ao: o, ao_status: $json.status || $json.detail || null } };

// ElevenLabs answers win. AgenticOrg only fills fields ElevenLabs left empty.
const KEYS = ["day_number","topic","class_happened","completed","group_a_result","group_b_result","group_c_result","what_went_well","what_went_wrong","how_to_improve","what_is_left","other_notes"];
const el = $json.el || {}, ao = $json.ao || {};
const has = v => v !== null && v !== undefined && String(v).trim() !== '';
const fb = {}, source = {};
for (const k of KEYS) { if (has(el[k])) { fb[k] = el[k]; source[k] = 'elevenlabs'; } else if (has(ao[k])) { fb[k] = ao[k]; source[k] = 'agenticorg'; } else { fb[k] = null; } }
const cap = s => has(s) ? String(s).trim().replace(/_/g, ' ').replace(/^./, c => c.toUpperCase()).replace(/^(No class|Not taught)$/i, m => m.charAt(0).toUpperCase() + m.slice(1).toLowerCase()) : null;
for (const k of ['completed', 'group_a_result', 'group_b_result', 'group_c_result']) fb[k] = cap(fb[k]);
if (fb.class_happened === false || fb.class_happened === 'false') fb.completed = 'No class';
const call = $('Prepare call').item.json, m = $('Match rows').item.json;
fb.next_step = fb.completed === 'No class' ? 'none' : fb.completed === 'No' ? 'repeat_day'
  : (fb.completed === 'Partly' || has(fb.how_to_improve)) ? 'replan_topic' : 'move_on';
fb.pending = Array.isArray(ao.pending) && ao.pending.length ? ao.pending : (has(fb.what_is_left) ? [{ group: null, what: fb.what_is_left }] : []);
fb.call_date = call.call_date; fb.conversation_id = call.conversation_id; fb.source = source;
// Find the row: exact day first, then the first open row of the topic.
const norm = s => String(s || '').toLowerCase().replace(/[^0-9a-z]/g, '');
let row = m.rows.find(r => norm(r.day) === norm(fb.day_number));
if (!row && has(fb.topic)) row = m.rows.find(r => !r.completed && norm(r.topic).includes(norm(fb.topic).replace(/^t\d+/, '')));
if (row) { fb.day_number = row.day; fb.topic = row.topic; }
// Plan rule: No = repeat the day; a second No on the same day = easier version.
const secondNo = fb.next_step === 'repeat_day' && row && /^no$/i.test(String(row.completed).trim());
fb.sheet = { 'Completed': fb.completed, 'What went well': fb.what_went_well, 'What went wrong': fb.what_went_wrong,
  'How to improve': fb.how_to_improve, 'What is left': fb.what_is_left, 'Reported on': fb.call_date };
return { json: { feedback: fb, row_number: row ? row.row_number : null, day: fb.day_number, topic: fb.topic,
  replan: !!row && (fb.next_step === 'replan_topic' || secondNo), make_easier: !!secondNo, agenticorg_status: $json.ao_status } };
